from pathlib import Path
import re,json
D=Path(__file__).resolve().parent;html=(D/'index.html').read_text();markup=html.split('<main>',1)[1].split('</main>',1)[0].replace('<h1>','<h3>').replace('</h1>','</h3>');markup=re.sub(r'id="([^"]+)"',r'data-condensed-role="\1"',markup)
viewer=(D/'viewer.js').read_text().replace('document.getElementById','get').replace("document.querySelector('.plot')","root.querySelector('.plot')").replace('window.CondensedReview','root.condensedReview').replace('function draw(){','function draw(){if(disposed)return;')
field=(D/'field-viewer.js').read_text().replace('document.getElementById','get').replace('window.CondensedFieldReview','root.condensedFieldReview').replace('CondensedReview','root.condensedReview').replace('function draw(){','function draw(){if(disposed)return;').replace('new ResizeObserver(draw).observe(plot);','const resizeObserver=new ResizeObserver(draw);resizeObserver.observe(plot);disposers.push(()=>resizeObserver.disconnect());')
code='''(function(){function render(item,hooks={}){if(item?.props?.scenario!=='phys.5.condensed.transition')return null;const root=document.createElement('section');root.className='card physics-condensed-lab';let disposed=false,mounted=false;const disposers=[];root.innerHTML='''+json.dumps(markup)+''';const get=key=>root.querySelector('[data-condensed-role="'+key+'"]');\n'''+viewer+'\n'+field+'''\nroot.getModelSpeech=()=>[...root.querySelectorAll('p')].map(p=>p.textContent).join(' ');if(hooks.speakButton)root.querySelector('h3').prepend(hooks.speakButton(root.getModelSpeech,'Read this transition activity aloud'));root.dispose=()=>{if(disposed)return;disposed=true;for(const f of disposers)f();root.dataset.disposed='true';};const lifecycle=new MutationObserver(()=>{if(root.isConnected)mounted=true;else if(mounted)root.dispose();});lifecycle.observe(document,{childList:true,subtree:true});disposers.push(()=>lifecycle.disconnect());return root;}window.PrimerCondensedLab={render};})();''';(D/'adapter.js').write_text(code)
css=html.split('<style>',1)[1].split('</style>',1)[0].replace('body{','.physics-condensed-lab{').replace('main{','.physics-condensed-lab{');css=re.sub(r'(?<=})([^{}]+)\{',lambda m:','.join('.physics-condensed-lab '+s.strip()if not s.strip().startswith('.physics-condensed-lab')else s.strip()for s in m[1].split(','))+'{',css);css=css.replace('.physics-condensed-lab svg{','.physics-condensed-lab [data-condensed-role="chart"]{');css+='\n.physics-condensed-lab{min-width:0;max-width:100%;box-sizing:border-box;overflow-wrap:anywhere}.physics-condensed-lab *{box-sizing:border-box}.physics-condensed-lab [data-condensed-role="fieldplot"]{display:block;width:100%;height:auto;min-width:0}\n';(D/'adapter.css').write_text(css)
(D/'adapter-test.html').write_text('<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="adapter.css"><body><script src="core-browser.js"></script><script src="field-browser.js"></script><script src="geometry-browser.js"></script><script src="adapter.js"></script><script>for(let i=0;i<2;i++)document.body.append(PrimerCondensedLab.render({props:{scenario:"phys.5.condensed.transition"}}));</script></body></html>')
